// Both callers require Retry-After seconds/date parsing, 3600-second ceiling and caller fallback.
export function retrySeconds(value: string | null, now: number, fallback = 5): number {
  if (value == null || value.trim() === '') return fallback;
  const normalized = value.trim();
  if (/^\d+$/.test(normalized)) {
    const seconds = Number(normalized);
    if (!Number.isSafeInteger(seconds)) return fallback;
    return Math.min(seconds, 3600);
  }
  const deadline = Date.parse(normalized);
  if (!Number.isFinite(deadline)) return fallback;
  const remaining = Math.ceil((deadline - now) / 1000);
  if (remaining < 0) return 0;
  return Math.min(remaining, 3600);
}

